INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT156-S2-Q11$batch02$, 156, 2, 11, $batch02$Flaw$batch02$, $batch02$Professor Williams: Professor Thomas’s report characterizes our colleague Professor York as too flamboyant and confrontational in the classroom. But the argument given in this report sounds so much like the classic argument of the self-serving academic that one has to wonder if Professor Thomas simply is not the orator and entertainer Thomas would like to be, and so vents frustrations by condemning others—Professor York in particular.$batch02$, $batch02$Professor Williams’s argument is flawed because it$batch02$, $batch02$D$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT156-S2-Q11$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$confuses the distinction between being overly confrontational and engaging students by entertaining them$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S2-Q11$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$presupposes the point it is attempting to establish$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S2-Q11$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$mistakes Professor Thomas’s characterization of a view for an endorsement of that view$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S2-Q11$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$attacks Professor Thomas personally rather than addressing Professor Thomas’s argument$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT156-S2-Q11$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$rejects the possibility that Professor York is in fact too confrontational.$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S2-Q11$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT156-S2-Q11$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion (implied)$batch02$, $batch02$Professor Thomas's criticism of York should be doubted.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Thomas's argument sounds self-serving, so Thomas may be venting jealousy.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Suppose Thomas really is jealous. Is York therefore not too confrontational? No. A jealous critic can still be right. Williams never looks at what Thomas actually said about York's teaching. The entire response is speculation about Thomas's motives.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Expect the ad hominem answer.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT156-S2-Q11$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$Williams draws no distinction between confrontational and entertaining teaching. He talks about Thomas's motives.$batch02$), ($batch02$B$batch02$, $batch02$The argument is weak, not circular. Williams does not assume Thomas is wrong in order to prove it.$batch02$), ($batch02$C$batch02$, $batch02$Williams treats the report as Thomas's own view, which it is. There is no characterization mistaken for endorsement.$batch02$), ($batch02$D$batch02$, $batch02$Williams attacks Thomas's possible jealousy and frustration rather than the report's reasoning. Even if Thomas is jealous, York might still be too confrontational.$batch02$), ($batch02$E$batch02$, $batch02$This tempts because Williams clearly sides with York. But Williams never denies outright that York could be too confrontational. The flaw is *how* he resists the report: by attacking Thomas.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT156-S2-Q11$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
